INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'mutuo-giovani-under-36-garanzia-prima-casa',
    'Mutuo giovani under 36: la garanzia statale sulla prima casa, come funziona',
    'Chi ha meno di 36 anni e un ISEE sotto la soglia prevista può accedere a un mutuo prima casa con una garanzia statale che copre gran parte del finanziamento. Come funziona in pratica.',
    'Come funziona la garanzia statale sul mutuo prima casa per gli under 36: requisiti, cosa copre e perché riduce l''anticipo necessario.',
    'mutui',
    '🔑',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il primo ostacolo per chi vuole comprare casa non è quasi mai la rata mensile, che spesso è confrontabile con un affitto: è l''anticipo. Le banche finanziano tipicamente fino all''80% del valore dell''immobile, il che significa dover avere già da parte il 20% più le spese notarili — una cifra che per molti under 36 alle prime armi è semplicemente fuori portata, anche a fronte di uno stipendio sufficiente a sostenere la rata.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">A cosa serve la garanzia statale</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per colmare esattamente questo divario esiste una garanzia pubblica sulla prima casa riservata a chi ha meno di 36 anni e un ISEE sotto la soglia prevista dalla normativa in vigore. Lo Stato garantisce una quota importante del mutuo verso la banca, il che permette agli istituti di credito di finanziare percentuali più alte del valore dell''immobile — in alcuni casi fino al 100% — riducendo drasticamente, o azzerando, l''anticipo che il richiedente deve avere da parte.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Requisiti principali</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Età</strong> — non aver compiuto 36 anni al momento della richiesta.</li><li><strong>ISEE</strong> — sotto la soglia stabilita dal decreto in vigore al momento della domanda (verificala sempre in banca o su fonti ufficiali aggiornate, perché queste misure vengono rifinanziate e modificate periodicamente).</li><li><strong>Prima casa</strong> — deve trattarsi dell''acquisto, con eventuale ristrutturazione, dell''abitazione principale, non di un investimento o di una seconda casa.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Oltre alla garanzia sul mutuo, chi rientra nei requisiti beneficia in genere anche di agevolazioni fiscali collegate all''acquisto della prima casa (esenzione da alcune imposte di trasferimento), che vanno verificate insieme al proprio notaio caso per caso.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Non è un mutuo a fondo perduto</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un punto spesso frainteso: la garanzia riduce l''anticipo richiesto e facilita l''accesso al credito, ma il mutuo va restituito per intero come qualunque altro — cambia chi si fa garante di una parte del rischio verso la banca, non l''importo che il richiedente deve rimborsare nel tempo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Simula la rata del tuo mutuo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Una volta ottenuto il finanziamento, il funzionamento della rata segue le stesse regole di ogni altro mutuo — tipicamente <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">ammortamento alla francese, con rata costante</a>. Su <a href="/mutui.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi tracciare il piano di ammortamento reale del tuo mutuo, quota capitale e quota interessi mese per mese, indipendentemente da come è stato ottenuto il finanziamento.</p>',
    'pubblicato',
    '2026-08-20 08:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'surroga-mutuo-cosa-e-come-funziona',
    'Surroga del mutuo: cos''è, come funziona e perché è sempre gratuita',
    'Portare il proprio mutuo su un''altra banca per ottenere condizioni migliori, senza costi e senza bisogno del consenso della banca originaria: ecco come funziona la surroga.',
    'Cos''è la surroga del mutuo, come funziona la portabilità verso un''altra banca, perché è gratuita per legge e quando conviene farla davvero.',
    'mutui',
    '🔄',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se hai acceso un mutuo qualche anno fa e oggi trovi in giro condizioni migliori — un tasso più basso, uno spread più conveniente — non sei costretto a restare con la banca originaria fino alla scadenza. Lo strumento che permette di cambiare banca mantenendo il mutuo si chiama <strong>surroga</strong> (o portabilità del mutuo).</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come funziona</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con la surroga, una nuova banca estingue il debito residuo verso la banca originaria e lo sostituisce con un nuovo contratto, alle condizioni concordate con te — stesso importo residuo, stessa garanzia ipotecaria (che viene semplicemente trasferita, non ricostituita da zero), ma tasso, spread e durata possono cambiare. Puoi anche scegliere di passare da variabile a fisso o viceversa in questo passaggio.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché è sempre gratuita</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La legge (nota informalmente come Bersani-bis, legge 40/2007) stabilisce che la surroga non può comportare alcun costo per chi la richiede: niente spese di istruttoria, niente penali di estinzione anticipata sul mutuo originario, niente nuove spese notarili a proprio carico per il trasferimento dell''ipoteca. La banca originaria, inoltre, non può rifiutarsi né opporre condizioni: non serve il suo consenso, solo una comunicazione.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Surroga o rinegoziazione: non è la stessa cosa</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un''alternativa spesso confusa con la surroga è la <strong>rinegoziazione</strong>: resti con la stessa banca, che accetta di modificare le condizioni del tuo mutuo esistente (di solito solo se sei un cliente in regola con i pagamenti). È più semplice sulla carta, ma la banca originaria non ha nessun obbligo di proporti condizioni realmente competitive, visto che non rischia di perderti come cliente — motivo per cui, prima di accettare una rinegoziazione, ha senso verificare cosa offrirebbe il mercato con una surroga.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quando conviene farla</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Conviene valutarla seriamente quando il divario tra il tuo tasso attuale e le condizioni di mercato è consistente e hai ancora diversi anni di durata residua davanti — più tempo resta, più anni di risparmio sugli interessi puoi ottenere dal cambio. Vale anche la pena calcolare l''impatto sul piano di ammortamento, visto che <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">nei primi anni la quota interessi pesa di più</a> sulla rata.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/mutui.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi confrontare rapidamente cosa cambierebbe nel tuo piano di ammortamento reale con un tasso diverso, così hai un numero concreto — non solo una sensazione — prima di iniziare le pratiche con una nuova banca.</p>',
    'pubblicato',
    '2026-08-20 08:10:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'etf-accumulazione-o-distribuzione-differenze',
    'ETF ad accumulazione o a distribuzione: quale scegliere',
    'La differenza tra un ETF che reinveste automaticamente i dividendi al suo interno e uno che te li distribuisce in contanti, e quale conviene in base al tuo obiettivo.',
    'Differenza tra ETF ad accumulazione e a distribuzione: come funzionano i dividendi, l''impatto fiscale e quale scegliere in base al tuo obiettivo.',
    'investimenti',
    '🔁',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando cerchi un ETF su un qualsiasi mercato ne trovi quasi sempre due versioni dello stesso indice: una con la sigla <strong>Acc</strong> (accumulazione) e una con la sigla <strong>Dist</strong> (distribuzione). La differenza riguarda un solo aspetto — cosa succede ai dividendi incassati dalle società o dalle obbligazioni contenute nell''indice — ma ha conseguenze pratiche diverse a seconda di cosa stai cercando di ottenere.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">ETF ad accumulazione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">I dividendi incassati dall''ETF non vengono distribuiti a te: restano dentro il fondo e vengono reinvestiti automaticamente, aumentando il valore della quota. Non ricevi nulla in contanti, ma il tuo capitale investito cresce grazie a quei dividendi reinvestiti senza che tu debba fare nulla — è l''opzione più comune per chi sta accumulando capitale nel lungo periodo e non ha bisogno di un flusso di cassa periodico dall''investimento.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">ETF a distribuzione</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">I dividendi vengono versati periodicamente (di solito trimestralmente o annualmente) direttamente sul tuo conto, in contanti. Il valore della quota non li incorpora: cresce meno nel tempo rispetto alla versione ad accumulazione a parità di indice, proprio perché quella parte di rendimento esce dal fondo invece di restarci reinvestita.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Quale conviene: dipende dalla fase</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Durante la fase di accumulo — quando stai costruendo capitale e non hai bisogno di reddito periodico dagli investimenti — la versione ad accumulazione è quasi sempre la scelta più efficiente, perché lascia lavorare <a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">l''interesse composto</a> senza interruzioni e senza che tu debba reinvestire manualmente i dividendi ricevuti.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nella fase di decumulo — ad esempio dopo aver raggiunto l''<a href="/news/indipendenza-finanziaria-fire-come-calcolare-il-numero" class="text-accent hover:underline font-medium">indipendenza finanziaria</a> e serve un flusso di cassa regolare per vivere — un ETF a distribuzione può semplificare la gestione, perché genera entrate periodiche senza dover vendere quote manualmente ogni volta che serve liquidità.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">L''aspetto fiscale</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">In entrambi i casi la tassazione italiana sulle plusvalenze e sui dividendi è la stessa aliquota, ma cambia <strong>quando</strong> si paga: con la distribuzione, l''imposta si applica a ogni stacco di dividendo lungo il percorso; con l''accumulazione, l''intero guadagno (incluso quello generato dai dividendi reinvestiti) viene tassato tutto insieme al momento della vendita — <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">ne parliamo nel dettaglio qui</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/investimenti.php" class="text-accent hover:underline font-medium">Reflexi</a> puoi tracciare entrambi i tipi di ETF nello stesso portafoglio, con il costo medio di carico aggiornato automaticamente a ogni acquisto.</p>',
    'pubblicato',
    '2026-08-20 08:20:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'tassazione-investimenti-etf-azioni-italia',
    'Tassazione di ETF, azioni e conto corrente in Italia: la guida essenziale',
    'Aliquote diverse per plusvalenze su ETF e azioni, titoli di Stato e conto corrente, e cosa significa in pratica il regime del risparmio amministrato usato dalla maggior parte dei broker.',
    'Come sono tassati ETF, azioni, titoli di Stato e conto corrente in Italia: aliquote, regime del risparmio amministrato e compensazione delle minusvalenze.',
    'investimenti',
    '🧾',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sapere quanto rende davvero un investimento, al netto delle tasse, richiede di conoscere un paio di regole di base della fiscalità italiana — non sono complicate, ma è facile confonderle se non le hai mai guardate tutte insieme.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le due aliquote principali</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>26%</strong> — l''aliquota standard su plusvalenze, dividendi e cedole per ETF, azioni, obbligazioni societarie e la gran parte degli strumenti finanziari.</li><li><strong>12,5%</strong> — aliquota agevolata riservata ai titoli di Stato italiani ed equiparati (ad esempio i titoli di Stato di paesi in una apposita white list), che pagano meno proprio per il loro ruolo di finanziamento del debito pubblico.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un ETF che investe in titoli di Stato italiani gode di un trattamento fiscale misto: la quota di rendimento riconducibile ai titoli di Stato è tassata al 12,5%, il resto al 26% — il broker o la banca gestiscono questo calcolo automaticamente, non serve farlo a mano.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Regime amministrato: la banca fa tutto da sola</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La quasi totalità dei broker e delle banche italiane applica il <strong>regime del risparmio amministrato</strong>: l''imposta viene trattenuta automaticamente a ogni vendita in plusvalenza, senza che tu debba inserire nulla nella dichiarazione dei redditi per quegli specifici investimenti. È l''opposto del regime dichiarativo, in cui saresti tu a dover calcolare e versare le imposte da solo — più complesso, e per questo scelto raramente da chi investe con un broker italiano.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Le minusvalenze si possono compensare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se vendi in perdita, quella minusvalenza non è persa: nel regime amministrato genera uno <em>zainetto fiscale</em> che puoi usare per compensare future plusvalenze dello stesso tipo (i cosiddetti redditi diversi, come quelli da ETF e azioni), entro il quarto anno solare successivo. Se non hai plusvalenze future con cui compensarla entro quel termine, la minusvalenza si perde.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">L''imposta di bollo, spesso dimenticata</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Oltre alla tassazione su plusvalenze e dividendi, esiste un''imposta di bollo dello 0,2% annuo calcolata sul controvalore complessivo degli strumenti finanziari detenuti (non sul guadagno), applicata a prescindere dal fatto che tu venda o meno — un costo fisso di detenzione da tenere presente nel calcolo del rendimento netto reale.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Vedi il rendimento reale del tuo portafoglio</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <a href="/calcolatore-rendimento.php" class="text-accent hover:underline font-medium">calcolatore di rendimento (ROI)</a> puoi stimare il guadagno lordo di un investimento; <a href="/investimenti.php" class="text-accent hover:underline font-medium">su Reflexi</a> il portafoglio tiene traccia del costo medio di carico reale di ogni posizione, la base di calcolo corretta per qualunque valutazione fiscale al momento della vendita.</p>',
    'pubblicato',
    '2026-08-20 08:30:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'ribilanciamento-portafoglio-cosa-e-perche',
    'Ribilanciare il portafoglio: cos''è e perché farlo periodicamente',
    'Con il passare del tempo le percentuali tra azionario, obbligazionario e altre asset class si spostano da sole, semplicemente perché crescono a velocità diverse. Cos''è il ribilanciamento.',
    'Cos''è il ribilanciamento del portafoglio, perché le percentuali tra asset class si spostano nel tempo, e come e ogni quanto farlo.',
    'investimenti',
    '⚖️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Immagina di partire con un portafoglio impostato al 70% azionario e 30% obbligazionario. Se in un anno l''azionario sale molto più dell''obbligazionario, la proporzione reale non è più 70/30: potrebbe essere diventata 78/22, senza che tu abbia fatto nulla. Il tuo portafoglio ha silenziosamente un livello di rischio diverso da quello che avevi scelto in origine.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cos''è il ribilanciamento</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ribilanciare significa riportare le percentuali del portafoglio verso l''allocazione target originaria, vendendo una parte di ciò che è cresciuto di più e/o indirizzando nuovi versamenti verso ciò che è rimasto indietro — così da mantenere nel tempo il profilo di rischio che avevi deciso consapevolmente, non quello che il mercato ha finito per assegnarti per inerzia.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Un effetto secondario: disciplina contrarian</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ribilanciare ha un effetto psicologico interessante: ti costringe sistematicamente a vendere un po'' di ciò che è salito e a comprare un po'' di ciò che è sceso — l''esatto opposto dell''istinto naturale di inseguire ciò che sta andando bene. Non garantisce un rendimento più alto, ma impone una disciplina che, storicamente, aiuta a evitare l''errore comportamentale più comune tra chi investe: comprare quando i prezzi sono già alti e vendere nel panico quando sono bassi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come e ogni quanto farlo</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Ribilanciamento a calendario</strong> — un controllo a intervalli fissi (ad esempio una volta l''anno), indipendentemente da quanto si sono mosse le percentuali.</li><li><strong>Ribilanciamento a soglia</strong> — si interviene solo quando una asset class si discosta dal target oltre una soglia prestabilita (ad esempio 5 punti percentuali), evitando aggiustamenti inutili per piccole oscillazioni.</li><li><strong>Ribilanciamento con i nuovi versamenti</strong> — invece di vendere, si indirizzano i versamenti futuri verso l''asset class rimasta indietro, un modo per riportare le proporzioni in linea senza generare una vendita (e quindi senza un evento fiscale imponibile).</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quest''ultimo approccio è spesso il più efficiente per chi investe con <a href="/news/pac-piano-accumulo-etf-come-funziona" class="text-accent hover:underline font-medium">versamenti periodici regolari</a>, perché evita di dover vendere in plusvalenza solo per riequilibrare — un dettaglio da considerare insieme a <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">come vengono tassate le plusvalenze</a> in Italia.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Guarda le proporzioni reali del tuo portafoglio</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/investimenti.php" class="text-accent hover:underline font-medium">Reflexi</a> vedi la composizione reale del tuo portafoglio aggiornata con le quotazioni live, utile per accorgersi subito di quanto si sono spostate le proporzioni rispetto a quelle desiderate — invece di scoprirlo solo dopo un anno intero.</p>',
    'pubblicato',
    '2026-08-20 08:40:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'tracciare-spese-manualmente-vs-collegamento-bancario',
    'Tracciare le spese a mano batte il collegamento automatico in banca? Ecco quando',
    'Collegare il conto in automatico sembra sempre la scelta più comoda, ma inserire le transazioni a mano ha un vantaggio concreto che il collegamento automatico elimina: la consapevolezza.',
    'Vantaggi e limiti del tracciamento manuale delle spese rispetto al collegamento automatico in banca, e perché la consapevolezza conta più della comodità.',
    'budget',
    '✍️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">La maggior parte delle app di finanza personale punta tutto sulla comodità: colleghi il conto una volta, e da quel momento ogni transazione appare da sola, senza dover fare nulla. È indubbiamente più veloce. Ma la velocità, in questo caso, ha un costo che raramente viene discusso: la <strong>consapevolezza</strong>.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il problema della frizione zero</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando ogni spesa viene registrata automaticamente e senza che tu debba farci caso, il cervello smette di elaborarla come una decisione. Diventa un dato che scorre in un elenco, non un''azione di cui sei stato consapevole nel momento in cui l''hai compiuta. Studi comportamentali sui pagamenti digitali mostrano da tempo un effetto simile: più il pagamento è indolore e invisibile, meno viene percepito come una spesa reale — è lo stesso motivo per cui pagare con la carta contactless porta quasi sempre a spendere di più rispetto a pagare in contanti.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa cambia inserendo le transazioni a mano</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Inserire manualmente una spesa, anche solo per pochi secondi, crea un piccolo momento di riflessione: quanto ho speso, per cosa, era necessario? Non è un dettaglio da poco su base quotidiana, ma nel tempo questo piccolo attrito ripetuto centinaia di volte l''anno costruisce una consapevolezza della propria spesa che il collegamento automatico, per design, elimina completamente.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">C''è anche un tema di sicurezza e privacy</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il collegamento automatico richiede di condividere le credenziali bancarie (o un accesso equivalente via open banking/PSD2) con un servizio terzo, che ottiene visibilità completa su ogni movimento del conto. Per chi preferisce non condividere questo livello di accesso, l''inserimento manuale resta l''unico modo di tenere un quadro completo delle proprie finanze senza collegare nulla a nessuno.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Non è una scelta tutto-o-niente</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il compromesso più comune è inserire manualmente le spese quotidiane più piccole (dove la consapevolezza conta di più) e registrare in blocco quelle grandi e ricorrenti come mutuo o bollette, dove il valore aggiunto della riflessione è minore. Serve comunque un controllo periodico per <a href="/news/abbonamenti-dimenticati-come-scovare-spese-ricorrenti" class="text-accent hover:underline font-medium">scovare eventuali abbonamenti dimenticati</a>, che sfuggono facilmente a entrambi gli approcci.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a> è costruito deliberatamente attorno all''inserimento manuale, senza collegamento bancario diretto: un limite per categoria con avviso prima di sforare funziona meglio quando sai davvero cosa hai inserito, categoria per categoria.</p>',
    'pubblicato',
    '2026-08-20 08:50:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'metodo-delle-buste-budget-digitale',
    'Metodo delle buste: cos''è e come applicarlo con un budget digitale',
    'Il metodo delle buste in contanti resta tra i più efficaci per chi fatica a rispettare un budget. Come replicarne la disciplina senza dover davvero usare contanti.',
    'Cos''è il metodo delle buste per il budget, perché funziona meglio di un limite generico, e come applicarlo con categorie digitali e rollover.',
    'budget',
    '✉️',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Prima delle app di finanza personale, il metodo delle buste in contanti (<em>envelope budgeting</em>) era già uno dei sistemi più citati per chi fatica a rispettare un budget. L''idea è semplice: prelevi lo stipendio, lo dividi in buste di carta — una per categoria (spesa, svago, trasporti) — e quando una busta è vuota, per quella categoria non spendi più fino al mese successivo.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché funziona meglio di un limite generico</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La forza del metodo non è organizzativa, è psicologica: un vincolo fisico (la busta vuota) è molto più difficile da ignorare di un numero astratto su un''app o su un foglio di calcolo. Non puoi «sforare leggermente» una busta vuota come faresti scorrendo un saldo digitale che sembra ancora capiente — il limite è tangibile, non negoziabile.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come replicarlo senza contanti</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non serve tornare davvero ai contanti per ottenere lo stesso effetto. Un <a href="/budget.php" class="text-accent hover:underline font-medium">budget per categoria</a> con un limite rigido per ogni voce di spesa e un avviso quando ti avvicini al tetto replica la stessa logica delle buste, ma con carte e bonifici: la categoria «diventa vuota» nello stesso modo, semplicemente in forma digitale invece che fisica.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Il rollover: un miglioramento rispetto alle buste originali</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un limite di questo metodo che una versione digitale può correggere: nel sistema tradizionale, quello che avanza in una busta a fine mese spesso «sparisce» o si mescola confusamente al mese successivo. Con un budget digitale che supporta il <strong>rollover</strong>, l''eccedenza non spesa in una categoria si riporta esplicitamente al mese dopo — utile per categorie con spese irregolari, come regali o manutenzioni, che non cadono uniformemente ogni mese. <a href="/news/regola-50-30-20-vs-budget-per-categoria" class="text-accent hover:underline font-medium">Ne parliamo anche qui</a>, a confronto con altri approcci di budget.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Da dove iniziare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Prima di impostare i limiti busta per busta, serve sapere quanto spendi davvero oggi in ogni categoria — altrimenti il rischio è fissare limiti arbitrari che non reggono al primo mese. Guardare 2-3 mesi di spese reali, come consigliato anche per <a href="/news/abbonamenti-dimenticati-come-scovare-spese-ricorrenti" class="text-accent hover:underline font-medium">scovare spese ricorrenti dimenticate</a>, è il punto di partenza più affidabile prima di definire ogni singolo tetto di categoria su <a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a>.</p>',
    'pubblicato',
    '2026-08-20 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'rapporto-debito-reddito-dti-cosa-e',
    'Rapporto debito/reddito (DTI): cos''è e perché conta anche se non chiedi un mutuo',
    'Le banche lo guardano per decidere se concederti un mutuo, ma è un indicatore utile da monitorare anche solo per farsi un''idea onesta della propria salute finanziaria.',
    'Cos''è il rapporto debito/reddito (DTI), come si calcola, la soglia indicativa che guardano le banche per un mutuo e perché monitorarlo comunque.',
    'pianificazione',
    '🧮',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Quando chiedi un mutuo, la banca non guarda solo il tuo reddito: guarda quanto di quel reddito è già impegnato in rate e debiti esistenti. Questo rapporto ha un nome preciso — <strong>rapporto debito/reddito</strong>, spesso indicato con la sigla inglese DTI (<em>debt-to-income</em>) — ed è uno dei numeri più importanti nella valutazione di qualunque richiesta di finanziamento.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come si calcola</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Si sommano tutte le rate mensili di debiti esistenti (mutuo, prestiti personali, finanziamenti auto, rate di carte revolving) e si divide per il reddito netto mensile. Se hai 500€ di rate mensili totali e un reddito netto di 2.000€, il tuo DTI è del 25%.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La soglia indicativa che guardano le banche</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Per la sola rata del nuovo mutuo, la prassi bancaria italiana (in linea con le indicazioni prudenziali di Banca d''Italia) considera generalmente sostenibile una rata che non superi circa il <strong>30-35% del reddito netto familiare</strong>. Non è una regola scritta nella legge in modo identico ovunque, ma è la soglia oltre la quale la maggior parte degli istituti inizia a valutare la richiesta come più rischiosa, a prescindere dal merito creditizio generale del richiedente.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Perché conta anche se non stai chiedendo un mutuo</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il DTI non è utile solo alle banche: è un indicatore onesto di quanto margine reale hai nel tuo bilancio. Un DTI basso significa più flessibilità per assorbire un imprevisto, risparmiare o investire; un DTI alto — anche se riesci a pagare tutte le rate puntualmente — significa che una parte consistente del tuo reddito è già vincolata prima ancora di iniziare a decidere come spenderlo. È un buon complemento a <a href="/news/patrimonio-netto-cos-e-perche-seguirlo-nel-tempo" class="text-accent hover:underline font-medium">seguire il proprio patrimonio netto nel tempo</a>: il patrimonio netto racconta cosa hai accumulato, il DTI racconta quanto margine hai oggi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come migliorarlo prima di chiedere un mutuo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se stai pianificando di chiedere un mutuo nei prossimi anni, ridurre debiti a rata più alta (come prestiti personali o finanziamenti auto) prima della richiesta abbassa il DTI e può migliorare sensibilmente le condizioni che ti vengono offerte — vale la pena valutarlo insieme a un eventuale <a href="/news/mutuo-tasso-fisso-o-variabile-come-scegliere" class="text-accent hover:underline font-medium">confronto tra tasso fisso e variabile</a> sul nuovo finanziamento.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/analisi.php" class="text-accent hover:underline font-medium">Reflexi</a>, avendo conti, ricorrenze e mutui già tracciati nello stesso posto, puoi farti un''idea rapida di quanto reddito mensile è già impegnato in rate fisse, senza doverlo ricalcolare a mano ogni volta.</p>',
    'pubblicato',
    '2026-08-20 09:10:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'finanze-di-coppia-conti-separati-o-cointestati',
    'Finanze di coppia: conti separati, cointestati, o un ibrido?',
    'Non esiste un modello giusto per tutte le coppie: conti completamente separati, completamente cointestati, o un ibrido con un conto comune per le spese condivise. Come scegliere.',
    'Come gestire le finanze in coppia: conti separati, cointestati o modello ibrido, e come dividere le spese comuni in modo equo quando i redditi sono diversi.',
    'pianificazione',
    '💞',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Gestire le finanze in coppia è uno dei temi su cui girano più opinioni nette e meno risposte universali. La verità è che non esiste un modello oggettivamente giusto: dipende da quanto guadagna ciascuno, da quanto a lungo si è insieme, e semplicemente da cosa fa sentire entrambi a proprio agio nel gestire il denaro condiviso.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Modello 1: tutto cointestato</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un unico conto dove confluisce tutto lo stipendio di entrambi, da cui escono tutte le spese, comuni e personali. Il vantaggio è la trasparenza totale e la semplicità operativa. Lo svantaggio è che richiede un livello di fiducia e allineamento molto alto sulle abitudini di spesa individuali, e può generare attrito se uno dei due percepisce di dover «giustificare» spese personali su un conto visto da entrambi.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Modello 2: tutto separato</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ognuno mantiene il proprio conto e la propria autonomia finanziaria completa, dividendo di volta in volta le spese comuni (affitto, spesa, bollette) con bonifici o pagamenti alternati. Massima autonomia individuale, ma richiede una contabilità continua delle spese condivise per restare eque nel tempo, e può complicarsi con obiettivi a lungo termine condivisi come un mutuo o un fondo di emergenza comune.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Modello 3: ibrido — un conto comune, due personali</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il modello scelto più spesso dalle coppie con redditi ben avviati: ognuno mantiene un conto personale per le spese individuali, e versa una quota su un conto comune dedicato esclusivamente alle spese condivise (casa, bollette, spesa, eventuale mutuo). Unisce buona parte della semplicità del conto unico alla piena autonomia personale su ciò che resta fuori dal conto comune.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Quanto versare a testa sul conto comune, quando i redditi sono diversi</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dividere le spese comuni esattamente a metà (50/50) sembra equo sulla carta, ma se i redditi sono molto diversi non lo è nella pratica: la stessa cifra pesa in modo molto diverso su chi guadagna meno. Un approccio più equo, usato spesso in questo modello ibrido, è versare sul conto comune una quota <strong>proporzionale al reddito</strong> di ciascuno, non un importo fisso identico — così entrambi contribuiscono con lo stesso sforzo relativo, non con la stessa cifra assoluta.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Qualunque modello, serve visibilità sull''insieme</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Indipendentemente dal modello scelto, avere una visione condivisa del quadro generale — <a href="/news/patrimonio-netto-cos-e-perche-seguirlo-nel-tempo" class="text-accent hover:underline font-medium">patrimonio netto complessivo</a>, obiettivi di risparmio comuni, eventuale mutuo cointestato — evita che decisioni importanti vengano prese con informazioni parziali da un solo lato della coppia. Su <a href="/budget.php" class="text-accent hover:underline font-medium">Reflexi</a> conti multipli, anche di intestatari diversi, possono convivere nello stesso quadro finanziario, utile per tenere sotto controllo sia l''autonomia personale che gli obiettivi condivisi.</p>',
    'pubblicato',
    '2026-08-20 09:20:00'
);
